-- =====================================================================
--  ERFWeb — test accounts for the filing walkthrough (004_seed_test_users.sql)
--  Adds a non-admin employee with a signature, two approvers in order, a Finance user,
--  the employee's approval route, sample per-diem rates, and department signatories.
--  Does NOT touch the admin account. Idempotent: safe to re-run.
--
--  All four log in with password: Test!1234   (test data — change before go-live)
--    employee1  Employee  files reports; approvers are manager1 (step 1) then manager2 (step 2)
--    manager1   Manager   first approver
--    manager2   Manager   second approver
--    finance1   Finance   physical-receipt tracking (Phase 3)
-- =====================================================================
BEGIN;

INSERT INTO departments (code, name) VALUES ('IMS', 'Information Management Systems')
ON CONFLICT (code) DO NOTHING;

-- employee1
INSERT INTO users (username, password_hash, full_name, position, email, mobile_no, department_id, role, signature, work_with_enabled, is_active)
VALUES (
  'employee1',
  '100000.B8L30Og09W5Ry1A0Jk9+iw==.iV0bfdI8W1/2YlJjLpMEz+WtkGfD0tzeFJi/EeBNySM=',
  'Test Employee',
  'Sales Representative',
  'employee1@example.local',
  NULL,
  (SELECT id FROM departments WHERE code = 'IMS'),
  'Employee',
  decode('', 'hex'),
  true,
  true
)
ON CONFLICT (username) DO NOTHING;

-- manager1
INSERT INTO users (username, password_hash, full_name, position, email, mobile_no, department_id, role, signature, work_with_enabled, is_active)
VALUES (
  'manager1',
  '100000.yc1nddWzv9kBDe12a/F/ag==.9fSiRVrx/gPHO8OJRWa64L86BI5z/f0s9wTFPnx8SgY=',
  'Test Manager One',
  'Department Manager',
  'manager1@example.local',
