ON CONFLICT (username) DO NOTHING;

-- Ordered approval route for employee1: manager1 first, then manager2.
INSERT INTO approval_routes (employee_user_id, step_order, approver_user_id)
SELECT e.id, 1, a.id FROM users e, users a WHERE e.username = 'employee1' AND a.username = 'manager1'
  AND NOT EXISTS (SELECT 1 FROM approval_routes r WHERE r.employee_user_id = e.id AND r.step_order = 1);
INSERT INTO approval_routes (employee_user_id, step_order, approver_user_id)
SELECT e.id, 2, a.id FROM users e, users a WHERE e.username = 'employee1' AND a.username = 'manager2'
  AND NOT EXISTS (SELECT 1 FROM approval_routes r WHERE r.employee_user_id = e.id AND r.step_order = 2);

-- Sample per-diem / transport rates for employee1 (test values).
INSERT INTO employee_rates (user_id, transport_rate, breakfast_rate, lunch_rate, dinner_rate, ot_meal_rate)
SELECT id, 0, 100, 150, 150, 100 FROM users WHERE username = 'employee1'
ON CONFLICT (user_id) DO NOTHING;

-- Signatory initials printed in the R47 footer for the IMS department.
INSERT INTO department_signatories (department_id, endorser_initials, reviewer_initials, approver_initials)
SELECT id, 'TM1', 'FINANCE', 'TM2' FROM departments WHERE code = 'IMS'
ON CONFLICT (department_id) DO NOTHING;

COMMIT;
